def f(g):
    Z=[(i,j) for i,row in enumerate(g) for j,x in enumerate(row) if x==0]
    rows_=sorted(set(i for i,_ in Z)); cols_=sorted(set(j for _,j in Z))
    H,W=len(g),len(g[0])
    o=[[g[i][j] for j in range(W)] for i in range(H)]
    for i in rows_:
        for j in range(W):
            if o[i][j]!=2: o[i][j]=0
    for i in range(H):
        for j in cols_: o[i][j]=0
    return o
